const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const entities=[['薇薇安长廊','Vivienne','地点','玻璃顶棚把街道变成室内。在这里，从马赛克地面、店铺与漫步者出发，阅读建筑如何成为商品的舞台。','薇薇安'],['维罗—多达长廊','Véro-Dodat','地点','导览将这里的大理石地面、杂货店招牌与演员拉歇尔联系起来。细小的装饰构成一座城市的记忆。','多达'],['全景画拱廊街','Passage des Panoramas','地点','从全景画到有顶商业长廊，观看本身成为一种消费。沿着图像、橱窗与人群的线索进入十九世纪。','全景画'],['歌剧院拱廊街','Passage de l’Opéra','地点','阅读室、股票投机与已经消失的走廊，在文档的多个卷轴中交叉出现。让消失的地点成为进入历史的门。','歌剧院拱廊街'],['开罗拱廊街','Passage du Caire','地点','平版印刷、商业传单与漏雨的玻璃屋顶，让这条长廊呈现商品流通背后的物质条件。','开罗拱廊街'],['波德莱尔','Charles Baudelaire','人物','以寓言、忧郁和震惊感受巴黎。跟随诗人进入人群，观察游荡者与商品世界之间的亲密距离。','波德莱尔'],['傅立叶','Charles Fourier','人物','从商业拱廊到集体住宅的想象：建筑与乌托邦在街心连廊里相遇。','傅立叶'],['奥斯曼','Georges-Eugène Haussmann','人物','林荫大道改变了巴黎的尺度，也改变了路障、交通与城市治理的关系。','奥斯曼'],['格兰维尔','J. J. Grandville','人物','在幻想图像中，时尚越过人体，商品的形态扩展到整个宇宙。','格兰维尔'],['本雅明','Walter Benjamin','人物','以引文、碎片与蒙太奇重新组织十九世纪的经验：在最细微的事物中辨认历史。','本雅明'],['达盖尔','Louis Daguerre','人物','在全景画、透景画与摄影之间，探索现代观看方式如何形成。','达盖尔']];
const portrait='https://upload.wikimedia.org/wikipedia/commons/7/71/F%C3%A9lix_Nadar_1820-1910_portraits_Charles_Baudelaire_1.jpg';
const art=`<svg viewBox="0 0 600 700" role="img" aria-label="玻璃顶棚与长廊的透视示意"><rect width="600" height="700" fill="#315346"/>${Array.from({length:9},(_,i)=>{let s=1-i*.095,x=300-270*s,y=360-330*s;return `<path d="M${x} 700V${y+160*s} Q300 ${y-100*s} ${600-x} ${y+160*s}V700" fill="none" stroke="#acb99c" stroke-width="${4*s}"/><path d="M${x} ${y+160*s}H${600-x}" stroke="#acb99c" fill="none"/>`}).join('')}<path d="M30 700L300 360 570 700M0 610H600M0 660H600M300 360V700" fill="none" stroke="#acb99c" stroke-width="2"/><text x="300" y="480" text-anchor="middle" fill="#e9e9df" font-size="21" font-family="Georgia">Passages de Paris</text></svg>`;
function links(list){return list.map(c=>`<a class="chapter-link reveal" href="#read/${c.id}">${esc(c.title)}<small>${c.paragraphs.length} 段导览材料 · 打开阅读 →</small></a>`).join('')}
function hits(term){let a=[];chapters.forEach(c=>c.paragraphs.forEach((p,i)=>{if(p.includes(term))a.push({c,p,i})}));return a}
function image(e){return e[0]==='波德莱尔'?`<figure class="image"><img src="${portrait}" alt="纳达尔拍摄的波德莱尔肖像" loading="lazy"><figcaption>纳达尔 · 波德莱尔肖像 · 公共领域</figcaption></figure>`:`<div class="image">${art}</div>`}
function home(){return `<section class="hero"><div class="hero-copy"><h1>在巴黎的<br>梦中漫游</h1><p>《拱廊街计划》的可视化阅读图谱。穿过长廊、人物与引文，进入十九世纪的城市经验。</p><a href="#library">进入卷轴书库 ↗</a><p class="note" style="color:#cbd4c4">不必从第一页开始。让一个地点，带你走向另一段历史。</p></div><div class="hero-art">${art}<figcaption>巴黎拱廊空间 · 透视示意</figcaption></div></section><section class="section intro"><div><h2>一本没有单一路径的书</h2><p>本雅明将拱廊、时尚、铁建筑、游荡者与历史理论并置。这里把导览拆成可以相互穿行的阅读入口，保留文档的引文编号和论述层次。</p><div class="paths"><a href="#places">沿着地点走</a><a href="#people">与人物相遇</a><a href="#random">拾取一段引文</a></div></div><blockquote>“拱廊街是一个城市，一个微缩的世界。”<p class="note">所提供导览 · [A1,1] · 引述《巴黎插图指南》</p></blockquote></section><section class="section"><h2>从六扇门进入巴黎</h2><div class="timeline">${['傅立叶','达盖尔','格兰维尔','波德莱尔','奥斯曼'].map(t=>`<a href="#entity/${entities.findIndex(e=>e[0]===t)}">${t}<br><small>${entities.find(e=>e[0]===t)[1]}</small></a>`).join('')}<a href="#search/室内">路易·菲利普<br><small>室内与痕迹</small></a></div></section><section class="section"><h2>阅读，仍在继续</h2><p>完整保留可继续扩充的卷轴、草稿和附录入口。已有材料可直接阅读；文档中的译文与解读仍需逐条对照正式版本。</p><a href="#library">浏览全部 ${chapters.length} 个阅读单元 →</a></section>`}
function library(term=''){return `<section class="section"><h1>卷轴书库</h1><p>按文档结构整理的 ${chapters.length} 个阅读单元。输入卷轴字母、地点、人物或笔记编号，检索全部材料。</p><label for="search">查找书中的线索</label><input id="search" type="search" placeholder="例如：A1,1、游荡者、铁建筑" value="${esc(term)}"><div id="results" class="listing">${links(chapters)}</div></section>`}
function search(term){let a=hits(term);$('#results').innerHTML=term?`<p>找到 ${a.length} 段相关材料</p>`+a.slice(0,180).map(h=>`<a class="chapter-link" href="#read/${h.c.id}/${h.i}"><strong>${esc(h.c.title)}</strong><small>${esc(h.p.slice(0,220))}…</small></a>`).join(''):links(chapters)}
function reader(id,pos){let c=chapters.find(c=>c.id===id);if(!c)return library();return `<div class="reading"><aside><a href="#library">← 返回书库</a>${chapters.map(x=>`<a href="#read/${x.id}" ${x.id===id?'aria-current="page"':''}>${esc(x.title)}</a>`).join('')}</aside><article><h1>${esc(c.title)}</h1><p class="note">来源：用户提供的《内容导览》 · 译文及笔记未完成版本校对</p><div class="tools"><button id="mark">${localStorage.getItem('read-'+id)?'已读':'标记为已读'}</button><a href="#notebook">写下札记 →</a></div>${c.paragraphs.map((p,i)=>`<p id="p${i}" class="${/\[[A-Za-z].*\]|英文原文/.test(p)?'fragment':''}">${esc(p.replace(/\*\*/g,''))}</p>`).join('')}<div class="tools">${+id>0?`<a href="#read/${+id-1}">← 上一单元</a>`:''}${+id<chapters.length-1?`<a href="#read/${+id+1}">下一单元 →</a>`:''}</div></article></div>`}
function entity(i){let e=entities[i];if(!e)return home();let a=hits(e[4]);return `<section class="section"><div class="place-row"><div><h1>${e[0]}</h1><p>${e[1]}</p><p>${e[3]}</p><p class="note">策展导读 · 基于所提供文档的概述</p></div>${image(e)}</div><h2>在书中遇见</h2><p>${a.length} 段相关导览材料。以下为文档摘录，点击可回到完整上下文。</p>${a.slice(0,40).map(h=>`<blockquote class="fragment"><p>${esc(h.p.slice(0,700))}${h.p.length>700?'…':''}</p><a href="#read/${h.c.id}/${h.i}">${esc(h.c.title)} · 阅读上下文 →</a></blockquote>`).join('')}<h2>继续这段漫游</h2><div class="paths">${entities.filter(x=>x!==e).slice(0,5).map(x=>`<a href="#entity/${entities.indexOf(x)}">${x[0]}</a>`).join('')}</div></section>`}
function render(){let [route,id,pos]=decodeURI(location.hash.slice(1)).split('/');let html='';if(route==='read')html=reader(id,pos);else if(route==='library'||route==='search')html=library(id||'');else if(route==='entity')html=entity(+id);else if(route==='places')html=`<section class="section"><h1>在长廊之间行走</h1><p>这是一条按阅读主题组织的漫游路线。点击地点，展开它在书中留下的痕迹。</p>${entities.filter(e=>e[2]==='地点').map(e=>`<div class="place-row reveal">${image(e)}<div><h2>${e[0]}</h2><p>${e[1]}</p><p>${e[3]}</p><a href="#entity/${entities.indexOf(e)}">走进这条长廊 →</a></div></div>`).join('')}</section>`;else if(route==='people')html=`<section class="section"><h1>人群中的面孔</h1><p>思想家、诗人与城市改造者，通过碎片发生关联。</p><div class="place-row">${image(entities[5])}<div><h2>波德莱尔的巴黎</h2><p>从寓言到游荡：把城市读成一首关于现代生活的诗。</p><a href="#entity/5">阅读波德莱尔 →</a></div></div><div class="people">${entities.filter(e=>e[2]==='人物').map(e=>`<a href="#entity/${entities.indexOf(e)}"><strong>${e[0]}</strong>${e[1]}<p>${e[3]}</p></a>`).join('')}</div></section>`;else if(route==='notebook')html=`<section class="section"><h1>我的阅读札记</h1><p>札记自动保存在当前浏览器中。换设备前，请先导出。</p><label for="notes">留下一个还未想清楚的问题</label><textarea id="notes" placeholder="今天，我在这座城市里看见……"></textarea><div class="tools"><button id="export">导出札记</button></div><h2>已读单元</h2>${links(chapters.filter(c=>localStorage.getItem('read-'+c.id)))||'<p>读完一个单元后，可以在阅读页标记。</p>'}</section>`;else if(route==='sources')html=`<section class="section"><h1>版本与资料</h1><p>文本来自用户提供的《内容导览.docx》，整理为 ${chapters.length} 个阅读单元、2251 段材料。导览包含译文、摘引和解读，并非经过校勘的《拱廊街计划》全文。保留文档中的原始编号；文档的引文归属、译文及历史细节仍待正式版本核对。</p><h2>继续补全</h2><p>下一阶段可为每个笔记补充所用版本、页码、原文、译文校订与相关图像。尚缺的内容不冒充已经完成的研究。</p><h2>图像与设计</h2><p>长廊图形为本网站绘制的空间透视示意，并非历史实景。波德莱尔肖像由纳达尔拍摄，公共领域。</p><a href="https://commons.wikimedia.org/wiki/File:F%C3%A9lix_Nadar_1820-1910_portraits_Charles_Baudelaire_1.jpg">肖像来源：Wikimedia Commons →</a><p>设计参考 <a href="https://github.com/Leonxlnx/taste-skill">Taste-skill</a> 的图像、文字与非模板化编排指导。</p></section>`;else if(route==='random'){let c=chapters[Math.floor(Math.random()*chapters.length)];location.hash='read/'+c.id+'/'+Math.floor(Math.random()*c.paragraphs.length);return}else html=home();$('#app').innerHTML=html;window.scrollTo(0,0);if($('#search')){$('#search').oninput=e=>search(e.target.value);if(id)search(id)}if($('#mark'))$('#mark').onclick=()=>{let key='read-'+id;if(localStorage.getItem(key))localStorage.removeItem(key);else localStorage.setItem(key,'1');render()};if($('#notes')){$('#notes').value=localStorage.getItem('arcades-notes')||'';$('#notes').oninput=e=>localStorage.setItem('arcades-notes',e.target.value);$('#export').onclick=()=>{let u=URL.createObjectURL(new Blob([$('#notes').value],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='拱廊街阅读札记.txt';a.click();URL.revokeObjectURL(u)}}if(pos!==undefined)setTimeout(()=>document.getElementById('p'+pos)?.scrollIntoView(),50)}window.addEventListener('hashchange',render);render();
